18	static int do_device_init(const struct init_entry *entry)
19	{
20		const struct device *dev = entry->dev;
21		int rc = 0;
22	
23		dev->state->init_res = 0;
24	
25		if (entry->init_fn.dev != NULL) {
26			rc = entry->init_fn.dev(dev);
27			/* Mark device initialized. If initialization
28			 * failed, record the error condition.
29			 */
30			if (rc != 0) {
31				if (rc < 0) {
32					rc = -rc;
33				}
34				if (rc > UINT8_MAX) {
35					rc = UINT8_MAX;
36				}
37				dev->state->init_res = rc;
38			}
39		}
40	
41		dev->state->initialized = true;
42	
43		return rc;
44	}
